 <script>
import {
  getCompanyInfo,
  getCompanyIotApiList,
  getCompanyIotApiGatewayList,
  getCompanyIotConfig,
  // eslint-disable-next-line no-unused-vars
  setCompanyIotConfig,
} from '@/api/user'

const defaultForm = {
  id: undefined,
  companyId: undefined,
  appId: '',
  appSecret: '',
  host: '',
  status: '1',
  param: '',
  api: [],
  serviceType: '',
}
export default {
  name: 'CompanyInfo',
  components: {
    ElPlusInput: () => import('@/components/form/ElPlusInput.vue'),
    ElPlusSelect: () => import('@/components/form/ElPlusSelect.vue'),
  },
  data() {
    return {
      drawer: false,
      direction: 'rtl',
      vipInfo: null,
      companyInfo: null,
      activeTab: 'first',
      apiFuncList: [],
      methodOptions: [
        { label: 'GET', value: 'GET' },
        { label: 'POST', value: 'POST' },
        { label: 'PUT', value: 'PUT' },
        { label: 'DELETE', value: 'DELETE' },
      ],
      form: Object.assign({}, defaultForm),
      apiConfigList: [],
      apiGatewayList: [],
      submitLoading: false,
    }
  },
  watch: {
    'form.serviceType': {
      handler(type, oldType) {
        const gateway = this.apiGatewayList.find((item) => item.key === type)
        if (gateway && oldType !== type  && !this.apiConfigList.length) {
          this.apiConfigList = gateway.api_map
        }
      },
    },
  },
  methods: {
    handleClose(done) {
      done()
    },
    async open(vipInfo) {
      this.vipInfo = vipInfo
      this.apiGatewayList = await getCompanyIotApiGatewayList()
      await this.getCompanyInfo()
      await this.initCompanyIotConfig()

      this.drawer = true
    },
    async getCompanyInfo() {
      this.companyInfo = await getCompanyInfo(this.vipInfo.id)
    },
    async initCompanyIotConfig() {
      const iotConfig = await getCompanyIotConfig(this.companyInfo.id)
      if (iotConfig) {
        this.form = Object.assign({}, iotConfig)
        this.apiConfigList = this.form.api
      }

      this.apiFuncList = await getCompanyIotApiList()
      if (!this.apiConfigList.length) {
        this.apiConfigList = this.apiFuncList.map((item) => {
          return {
            funCode: item.value,
            title: item.name,
            url: '',
            method: 'POST',
            keyMap: '',
            param: '',
          }
        })
      }
    },
    // eslint-disable-next-line no-unused-vars
    onTabChange(tab) {
      // console.log('tab:', tab)
    },
    handleDelete(index, row) {
      console.log(index, row)
    },
    cancel() {
      this.form = Object.assign({}, defaultForm)
      this.$refs.iotForm.resetFields()
      this.$refs.iotForm.clearValidate()
      this.drawer = false
    },
    // eslint-disable-next-line no-unused-vars
    onServiceTypeChange(type) {},
    submit() {
      this.form.api = this.apiConfigList
      this.submitLoading = true
      setCompanyIotConfig(this.companyInfo.id, this.form)
        .then(() => {
          this.$message.success('提交成功')
          this.submitLoading = false
          this.cancel()
          this.$emit('ok')
        })
        // eslint-disable-next-line no-unused-vars
        .catch((_err) => {
          setTimeout(() => {
            this.submitLoading = false
          }, 1000)
          // this.$message.error(_err.message)
        })
    },
  },
}
</script>
